#include "pico/stdlib.h"
#include "hardware/pio.h"
#include "audio_converter.pio.h" // Generated by pioasm
#include "hardware/clocks.h"
#include "hardware/structs/pll.h"
#include "hardware/structs/clocks.h"
#include "hardware/dma.h"
#include "pico/multicore.h"
#include "dac.h"
#include "tusb.h"

#define CLK_SCK_256FS_IN_PIN 22
#define CLK_SCK_64FS_OUT_PIN 21

#define RX_PIO_BASE_PIN 2 /* DATA, LRCK, SCK */
#define TX_PIO_BASE_PIN 5 /* DATA(out), LRCK(out), SCK_64fs(in) */
#define _TX_PIO_DATA_PIN (TX_PIO_BASE_PIN)
#define _TX_PIO_LRCK_PIN (TX_PIO_BASE_PIN + 1)
#define _TX_PIO_SCK_PIN (TX_PIO_BASE_PIN + 2)

#define BUFFER_SIZE_SAMPLES 32
#define CHANNELS 2

typedef struct {
    __attribute__((aligned(8))) uint32_t *in_ctl_desc[2];
    __attribute__((aligned(8))) uint32_t *out_ctl_desc[2];
    PIO pio;
    uint in_sm, out_sm;
    /* DMA ping-pong buffer */
    uint in_ctl_ch, in_dat_ch;
    uint out_ctl_ch, out_dat_ch;
    uint32_t buf_in[2][BUFFER_SIZE_SAMPLES * CHANNELS];
    uint32_t buf_out[2][BUFFER_SIZE_SAMPLES * CHANNELS];
    bool rx_sync;
} AudioConv;

#include "osal/osal.h"
/* core #1 -> core #0 */
typedef enum {
    AUDIO_MSG_NULL = 0,
    AUDIO_MSG_DATA_READY_1 = 1,
    AUDIO_MSG_DATA_READY_2 = 2
} _audio_msg_t;

#define _AUDIO_SAMPLE_SIZE sizeof(Audio_sample_t)
#define _AUDIO_FIFO_DEPTH (BUFFER_SIZE_SAMPLES * 4)
typedef struct {
  // FIFO
  tu_fifo_t ff;
  uint8_t ff_buf[_AUDIO_SAMPLE_SIZE * _AUDIO_FIFO_DEPTH];
  OSAL_MUTEX_DEF(ff_mutex_w);
  OSAL_MUTEX_DEF(ff_mutex_r);
  Audio_sample_t *sm[2]; /* pointer to shared memory */
} _audio_uac_ctx;

#define REL_IRQ_NUM(_IRQ, _SM) (((_IRQ) % 4) + ((_SM + (_IRQ)) & 3));
static AudioConv *_irq_rx_sync_args;
void _irq_rx_sync(void){
    AudioConv *ctx = _irq_rx_sync_args;
    irq_set_enabled(pio_get_irq_num(ctx->pio, 0), false);
    while(pio_sm_get_rx_fifo_level(ctx->pio, 0) != 0){
        pio_sm_get(ctx->pio, 0);
    }
    pio_sm_set_enabled(ctx->pio, ctx->out_sm, true);
    dma_channel_start(ctx->out_ctl_ch);
    dma_channel_start(ctx->in_ctl_ch);
    ctx->rx_sync = true;
}

static void process_audio(const uint32_t* input, uint32_t* output, size_t num_frames) {
    // Just copy the input to the output
    for (size_t i = 0; i < num_frames * 2; i++) {
        /* FIXME: 要調査, オシロスコープを見ると、有効データは 18 bit っぽい
            出力（DAC, USB は、今のところ MSB（[31:]）に有効データを入れる必要があるので、シフトする。
            input:   xxxx_xxxx_xxxx_xxDD_DDDD_DDDD_DDDD_DDDD
            output:  DDDD_DDDD_DDDD_DDDD_DDxx_xxxx_xxxx_xxxx
        */
        output[i] = input[i] << 14;
    }
}
static AudioConv *_irq_dma_arg;
static void dma_i2s_in_handler(void) {
    /* We're double buffering using chained TCBs. By checking which buffer the
     * DMA is currently reading from, we can identify which buffer it has just
     * finished reading (the completion of which has triggered this interrupt).
     */
    AudioConv *arg = _irq_dma_arg;
    if (*(int32_t**)dma_hw->ch[arg->in_ctl_ch].read_addr == arg->buf_in[0]) {
        // It is inputting to the second buffer so we can overwrite the first
        process_audio(arg->buf_in[0], arg->buf_out[0], BUFFER_SIZE_SAMPLES * CHANNELS);
        multicore_fifo_push_blocking((_audio_msg_t)AUDIO_MSG_DATA_READY_1);
    } else {
        // It is currently inputting the first buffer, so we write to the second
        process_audio(arg->buf_in[1], arg->buf_out[1], BUFFER_SIZE_SAMPLES * CHANNELS);
        multicore_fifo_push_blocking((_audio_msg_t)AUDIO_MSG_DATA_READY_2);
    }
    dma_hw->ints0 = 1u << arg->in_dat_ch;  // clear the IRQ
}

void AudioConv_init(AudioConv *this, PIO pio, int pin_base_in, int pin_base_out){
    /* init input SM */
    this->pio = pio;
    uint offset_rx = pio_add_program(this->pio, &audio_rj_rx_program);
    this->in_sm = pio_claim_unused_sm(this->pio, true);
    audio_rj_rx_program_init(this->pio, this->in_sm, offset_rx, pin_base_in);

    /* Initialize Tx DMA channel */
    /* 
      1. ctl ch を起動
      2. ctl ch により、in_ctl_desc に格納された転送先バッファのアドレスが data ch. の転送先アドレスレジスタに格納される
         同時に、ctl ch の転送元アドレスが次に進む。アドレス 3 bit でラップアラウンドするので、ctl_desc[0], ctl_desc[1] を交互に繰り返す。
         同時に、data ch が起動する（転送先アドレスレジスタのエイリアス al2_write_addr_trig に書き込むとそうなる）
      3. data ch の転送が完了する。同時に、割り込みが発生する（dma_i2s）
      4. chain で指定された、ctl_ch が起動する。
      5. [2] に戻る。
     */
    this->in_ctl_ch = dma_claim_unused_channel(true);
    this->in_dat_ch = dma_claim_unused_channel(true);
    this->in_ctl_desc[0] = &(this->buf_in[0][0]);
    this->in_ctl_desc[1] = &(this->buf_in[1][0]);

    dma_channel_config c = dma_channel_get_default_config(this->in_ctl_ch);
    channel_config_set_read_increment(&c, true);
    channel_config_set_write_increment(&c, false);
    channel_config_set_ring(&c, false, 3);
    channel_config_set_transfer_data_size(&c, DMA_SIZE_32);
    dma_channel_configure(this->in_ctl_ch, &c, &dma_hw->ch[this->in_dat_ch].al2_write_addr_trig, this->in_ctl_desc, 1, false);

    c = dma_channel_get_default_config(this->in_dat_ch);
    channel_config_set_read_increment(&c, false);
    channel_config_set_write_increment(&c, true);
    channel_config_set_chain_to(&c, this->in_ctl_ch);
    channel_config_set_dreq(&c, pio_get_dreq(this->pio, this->in_sm, false));
    dma_channel_configure(this->in_dat_ch,
                          &c,
                          NULL,                            // Will be set by ctrl chan
                          &this->pio->rxf[this->in_sm],    // Source pointer
                          BUFFER_SIZE_SAMPLES * CHANNELS,  // Number of transfers
                          false                            // Don't start yet
    );

    /* Init output SM */
    uint off_tx = pio_add_program(this->pio, &audio_lj_tx_program);
    this->out_sm = pio_claim_unused_sm(this->pio, true);
    audio_lj_tx_program_init(this->pio,
        this->out_sm,
        off_tx,
        pin_base_out,       // DATA
        pin_base_out + 1,   // LRCK
        pin_base_out + 2);  // BCK

    /* Initialize Rx DMA channel */
    this->out_ctl_ch = dma_claim_unused_channel(true);
    this->out_dat_ch = dma_claim_unused_channel(true);
    this->out_ctl_desc[0] = &this->buf_out[0][0];
    this->out_ctl_desc[1] = &this->buf_out[1][0];
    
    c = dma_channel_get_default_config(this->out_ctl_ch);
    channel_config_set_read_increment(&c, true);
    channel_config_set_write_increment(&c, false);
    channel_config_set_ring(&c, false, 3);
    channel_config_set_transfer_data_size(&c, DMA_SIZE_32);
    dma_channel_configure(this->out_ctl_ch, &c, &dma_hw->ch[this->out_dat_ch].al3_read_addr_trig, this->out_ctl_desc, 1, false);

    c = dma_channel_get_default_config(this->out_dat_ch);
    channel_config_set_read_increment(&c, true);
    channel_config_set_write_increment(&c, false);
    channel_config_set_chain_to(&c, this->out_ctl_ch);
    channel_config_set_dreq(&c, pio_get_dreq(this->pio, this->out_sm, true));

    dma_channel_configure(this->out_dat_ch,
                          &c,
                          &this->pio->txf[this->out_sm],  // Destination pointer
                          NULL,                          // Source pointer, will be set by ctrl channel
                          BUFFER_SIZE_SAMPLES * CHANNELS,            // Number of transfers
                          false                          // Start immediately
    );
    
    _irq_dma_arg = this;
    irq_set_exclusive_handler(DMA_IRQ_0, dma_i2s_in_handler);
    dma_channel_set_irq0_enabled(this->in_dat_ch, true);
    irq_set_enabled(DMA_IRQ_0, true);

    this->rx_sync = false;
    _irq_rx_sync_args = this;
    irq_set_exclusive_handler(pio_get_irq_num(this->pio, 0), _irq_rx_sync);
    irq_set_priority(pio_get_irq_num(this->pio, 0), PICO_DEFAULT_IRQ_PRIORITY);
    irq_clear(pio_get_irq_num(this->pio, 0));
    pio_set_irq0_source_enabled(this->pio, pis_interrupt0, true);
    irq_set_enabled(pio_get_irq_num(this->pio, 0), true);
    
    pio_sm_set_enabled(this->pio, this->in_sm, true);


}

static AudioConv __attribute__((aligned(8))) i2s;

static void dac_start(void) {

    /* SCK 分周 */
    clock_gpio_init(CLK_SCK_64FS_OUT_PIN, CLOCKS_CLK_GPOUT0_CTRL_AUXSRC_VALUE_CLKSRC_GPIN1, 4);
    clock_configure_gpin(clk_gpout0, CLK_SCK_256FS_IN_PIN, 8192000, 8192000/4);
    
    AudioConv_init(&i2s, pio0, RX_PIO_BASE_PIN, TX_PIO_BASE_PIN);

    // Main loop
    while (true) {
        /* uint32_t data = pio_sm_get_blocking(pio_rx, sm_rx);
        pio_sm_put_blocking(pio_tx, sm_tx, data); */
    }

    return;
}


static _audio_uac_ctx _uacctx;

static void _cpu0_sio_irq_handler(void){
    if(multicore_fifo_rvalid()){
        _audio_msg_t msg = (_audio_msg_t)multicore_fifo_pop_blocking();
        switch(msg){
            case AUDIO_MSG_DATA_READY_1:
                // tu_fifo_write_n(&_uacctx.ff, (void *)_uacctx.sm[0], BUFFER_SIZE_SAMPLES);
                tud_audio_write((void *)_uacctx.sm[0], CFG_TUD_AUDIO_FUNC_1_N_BYTES_PER_SAMPLE_TX * CFG_TUD_AUDIO_FUNC_1_N_CHANNELS_TX * BUFFER_SIZE_SAMPLES);
                break;
            case AUDIO_MSG_DATA_READY_2:
                // tu_fifo_write_n(&_uacctx.ff, (void *)_uacctx.sm[1], BUFFER_SIZE_SAMPLES);
                tud_audio_write((void *)_uacctx.sm[1], CFG_TUD_AUDIO_FUNC_1_N_BYTES_PER_SAMPLE_TX * CFG_TUD_AUDIO_FUNC_1_N_CHANNELS_TX * BUFFER_SIZE_SAMPLES);
                break;
            default:
                break;
        }
    }
    multicore_fifo_clear_irq();
}

/* runs on CPU0 */
void audio_init(void){
    _audio_uac_ctx *ctx = &_uacctx;
    /* 
        tu_fifo_config(&ctx->ff, ctx->ff_buf, TU_ARRAY_SIZE(ctx->ff_buf) / _AUDIO_SAMPLE_SIZE), _AUDIO_SAMPLE_SIZE, true);
        osal_mutex_t mutex_rd = osal_mutex_create(&ctx->ff_mutex_r);
        osal_mutex_t mutex_wr = osal_mutex_create(&ctx->ff_mutex_w);
        TU_ASSERT(mutex_rd != NULL && mutex_wr != NULL, );
        tu_fifo_config_mutex(&ctx->ff, mutex_wr, mutex_rd);
    */
    ctx->sm[0] = (Audio_sample_t *)i2s.buf_out[0];
    ctx->sm[1] = (Audio_sample_t *)i2s.buf_out[1];

    irq_set_exclusive_handler(SIO_FIFO_IRQ_NUM(0), _cpu0_sio_irq_handler);
    irq_set_enabled(SIO_FIFO_IRQ_NUM(0), true);

    multicore_launch_core1(dac_start);
}

static size_t _audio_get_fifo_count(_audio_uac_ctx *ctx){
    return (size_t)tu_fifo_count(&ctx->ff);
}

static size_t _audio_get_samples(_audio_uac_ctx *ctx, Audio_sample_t *buf, size_t n){
    return (size_t)tu_fifo_read_n(&ctx->ff, (void *)buf, n);
}

size_t Audio_get_fifo_count(void){
    return _audio_get_fifo_count(&_uacctx);
}

size_t Audio_get_samples(Audio_sample_t *buf, size_t n){
    return _audio_get_samples(&_uacctx, buf, n);
}
